SELECT
 MT.BOOKINGS_MEASURE_KEY,
 MT.BKGS_MEASURE_TRANS_TYPE_CODE,
 MT.BOOKINGS_PROCESS_DATE,
 MT.SALES_TERRITORY_KEY,
 MT.SALES_REP_NUMBER,
 MT.DV_CONTRACT_DURATION,
 MT.DV_ANNUALIZED_FLG,
 MT.RU_SERVICE_CONTRACT_START_DTM,
 MT.RU_SERVICE_CONTRACT_END_DTM,
 MT.ANNUITY_TYPE,
 MT.ANNUITY_MONTH,
 MT.PER_MONTH_AMT  *12   ANNUITY_AMT,
 MT.DV_FMV_FLG,
 MT.ADJUSTMENT_CODE
 FROM
 {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_23') }} MT
 INNER JOIN
  {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY') }} ALL_TRIPS
 ON ALL_TRIPS.BOOKINGS_MEASURE_KEY = MT.BOOKINGS_MEASURE_KEY
 AND ALL_TRIPS.BKGS_MEASURE_TRANS_TYPE_CODE = MT.BKGS_MEASURE_TRANS_TYPE_CODE
 AND ALL_TRIPS.BOOKINGS_PROCESS_DATE = MT.BOOKINGS_PROCESS_DATE
 AND ALL_TRIPS.SALES_TERRITORY_KEY = MT.SALES_TERRITORY_KEY
 AND ALL_TRIPS.SALES_REP_NUMBER = MT.SALES_REP_NUMBER
 WHERE
 COLLATE(  ALL_TRIPS.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY322' AND COLLATE( MT.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3'
 AND ANNUITY_MONTH > MT.BOOKINGS_PROCESS_MONTH
 AND (MT.BOOKINGS_MEASURE_KEY, MT.BKGS_MEASURE_TRANS_TYPE_CODE, MT.BOOKINGS_PROCESS_DATE, MT.SALES_TERRITORY_KEY, MT.SALES_REP_NUMBER, MT.ANNUITY_TYPE, MT.ANNUITY_MONTH)
 NOT IN (
  SELECT
   MT1.BOOKINGS_MEASURE_KEY,
   MT1.BKGS_MEASURE_TRANS_TYPE_CODE,
   MT1.BOOKINGS_PROCESS_DATE,
   MT1.SALES_TERRITORY_KEY,
   MT1.SALES_REP_NUMBER,
   MT1.ANNUITY_TYPE,
   MAX(ANNUITY_MONTH)  ANNUITY_MONTH
   FROM
   {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_23') }} MT1
   INNER JOIN
    {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY') }} ALL_TRIPS1
   ON ALL_TRIPS1.BOOKINGS_MEASURE_KEY = MT1.BOOKINGS_MEASURE_KEY
   AND ALL_TRIPS1.BKGS_MEASURE_TRANS_TYPE_CODE = MT1.BKGS_MEASURE_TRANS_TYPE_CODE
   AND ALL_TRIPS1.BOOKINGS_PROCESS_DATE = MT1.BOOKINGS_PROCESS_DATE
   AND ALL_TRIPS1.SALES_TERRITORY_KEY = MT1.SALES_TERRITORY_KEY
   AND ALL_TRIPS1.SALES_REP_NUMBER = MT1.SALES_REP_NUMBER
    WHERE
   COLLATE( MT1.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3' AND COLLATE( ALL_TRIPS1.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY322'
    GROUP BY
   MT1.BOOKINGS_MEASURE_KEY,MT1.BKGS_MEASURE_TRANS_TYPE_CODE,MT1.BOOKINGS_PROCESS_DATE,MT1.SALES_TERRITORY_KEY,MT1.SALES_REP_NUMBER,MT1.ANNUITY_TYPE )
   UNION ALL
   SELECT
 MT.BOOKINGS_MEASURE_KEY,
 MT.BKGS_MEASURE_TRANS_TYPE_CODE,
 MT.BOOKINGS_PROCESS_DATE,
 MT.SALES_TERRITORY_KEY,
 MT.SALES_REP_NUMBER,
 MT.DV_CONTRACT_DURATION,
 MT.DV_ANNUALIZED_FLG,
 MT.RU_SERVICE_CONTRACT_START_DTM,
 MT.RU_SERVICE_CONTRACT_END_DTM,
 MT.ANNUITY_TYPE,
 MT.ANNUITY_MONTH,
 MT.PER_MONTH_AMT  *    (MOD(MT.DV_CONTRACT_DURATION, 12) )     ANNUITY_AMT,
 MT.DV_FMV_FLG,
 MT.ADJUSTMENT_CODE
 FROM
 {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_23') }} MT
 INNER JOIN
  {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY') }} ALL_TRIPS
 ON ALL_TRIPS.BOOKINGS_MEASURE_KEY = MT.BOOKINGS_MEASURE_KEY
 AND ALL_TRIPS.BKGS_MEASURE_TRANS_TYPE_CODE = MT.BKGS_MEASURE_TRANS_TYPE_CODE
 AND ALL_TRIPS.BOOKINGS_PROCESS_DATE = MT.BOOKINGS_PROCESS_DATE
 AND ALL_TRIPS.SALES_TERRITORY_KEY = MT.SALES_TERRITORY_KEY
 AND ALL_TRIPS.SALES_REP_NUMBER = MT.SALES_REP_NUMBER
 WHERE
 COLLATE(  ALL_TRIPS.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY322' AND COLLATE( MT.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3'
 AND ANNUITY_MONTH > MT.BOOKINGS_PROCESS_MONTH
  AND (MT.BOOKINGS_MEASURE_KEY, MT.BKGS_MEASURE_TRANS_TYPE_CODE, MT.BOOKINGS_PROCESS_DATE, MT.SALES_TERRITORY_KEY, MT.SALES_REP_NUMBER, MT.ANNUITY_TYPE, MT.ANNUITY_MONTH)
 IN (
  SELECT
   MT1.BOOKINGS_MEASURE_KEY,
   MT1.BKGS_MEASURE_TRANS_TYPE_CODE,
   MT1.BOOKINGS_PROCESS_DATE,
   MT1.SALES_TERRITORY_KEY,
   MT1.SALES_REP_NUMBER,
   MT1.ANNUITY_TYPE,
   MAX(ANNUITY_MONTH)  ANNUITY_MONTH
   FROM
   {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_23') }} MT1
   INNER JOIN
    {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY') }} ALL_TRIPS1
   ON ALL_TRIPS1.BOOKINGS_MEASURE_KEY = MT1.BOOKINGS_MEASURE_KEY
   AND ALL_TRIPS1.BKGS_MEASURE_TRANS_TYPE_CODE = MT1.BKGS_MEASURE_TRANS_TYPE_CODE
   AND ALL_TRIPS1.BOOKINGS_PROCESS_DATE = MT1.BOOKINGS_PROCESS_DATE
   AND ALL_TRIPS1.SALES_TERRITORY_KEY = MT1.SALES_TERRITORY_KEY
   AND ALL_TRIPS1.SALES_REP_NUMBER = MT1.SALES_REP_NUMBER
    WHERE
   COLLATE( MT1.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3' AND COLLATE( ALL_TRIPS1.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY322'
   GROUP BY
   MT1.BOOKINGS_MEASURE_KEY,MT1.BKGS_MEASURE_TRANS_TYPE_CODE,MT1.BOOKINGS_PROCESS_DATE,MT1.SALES_TERRITORY_KEY,MT1.SALES_REP_NUMBER,MT1.ANNUITY_TYPE )
  AND MOD(  MT.DV_CONTRACT_DURATION, 12) <> 0

UNION ALL
   SELECT
 MT.BOOKINGS_MEASURE_KEY,
 MT.BKGS_MEASURE_TRANS_TYPE_CODE,
 MT.BOOKINGS_PROCESS_DATE,
 MT.SALES_TERRITORY_KEY,
 MT.SALES_REP_NUMBER,
 MT.DV_CONTRACT_DURATION,
 MT.DV_ANNUALIZED_FLG,
 MT.RU_SERVICE_CONTRACT_START_DTM,
 MT.RU_SERVICE_CONTRACT_END_DTM,
 MT.ANNUITY_TYPE,
 MT.BOOKINGS_PROCESS_MONTH  ANNUITY_MONTH,
 MT.PER_MONTH_AMT  * (MT.ANNUITY_NUMBER-1 ) *12  ANNUITY_AMT,
 MT.DV_FMV_FLG,
 MT.ADJUSTMENT_CODE
 FROM
 {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_23') }} MT
 INNER JOIN
  {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY') }} ALL_TRIPS
 ON ALL_TRIPS.BOOKINGS_MEASURE_KEY = MT.BOOKINGS_MEASURE_KEY
 AND ALL_TRIPS.BKGS_MEASURE_TRANS_TYPE_CODE = MT.BKGS_MEASURE_TRANS_TYPE_CODE
 AND ALL_TRIPS.BOOKINGS_PROCESS_DATE = MT.BOOKINGS_PROCESS_DATE
 AND ALL_TRIPS.SALES_TERRITORY_KEY = MT.SALES_TERRITORY_KEY
 AND ALL_TRIPS.SALES_REP_NUMBER = MT.SALES_REP_NUMBER
  WHERE
 COLLATE( MT.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3' AND COLLATE( ALL_TRIPS.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY322'
  AND ANNUITY_MONTH > MT.BOOKINGS_PROCESS_MONTH
   QUALIFY
 ANNUITY_NUMBER = MIN(ANNUITY_NUMBER) OVER (PARTITION BY MT.BOOKINGS_MEASURE_KEY                 ,
 MT.BKGS_MEASURE_TRANS_TYPE_CODE             ,
 MT.BOOKINGS_PROCESS_DATE  ,MT.SALES_TERRITORY_KEY,MT.SALES_REP_NUMBER,
 MT.ANNUITY_TYPE)

UNION ALL
   SELECT
 MT.BOOKINGS_MEASURE_KEY,
 MT.BKGS_MEASURE_TRANS_TYPE_CODE,
 MT.BOOKINGS_PROCESS_DATE,
 MT.SALES_TERRITORY_KEY,
 MT.SALES_REP_NUMBER,
 MT.DV_CONTRACT_DURATION,
 MT.DV_ANNUALIZED_FLG,
 MT.RU_SERVICE_CONTRACT_START_DTM,
 MT.RU_SERVICE_CONTRACT_END_DTM,
 MT.ANNUITY_TYPE,
 MT.BOOKINGS_PROCESS_MONTH ANNUITY_MONTH,
 MT.DV_MULTIYEAR_US_NET_AMT    ANNUITY_AMT,
 MT.DV_FMV_FLG,
 MT.ADJUSTMENT_CODE
 FROM
 {{ source('raw', 'WI_MT_RSTD_BKGS_MEASURE') }} MT
 INNER JOIN
  {{ source('raw', 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY') }} ALL_TRIPS
 ON ALL_TRIPS.BOOKINGS_MEASURE_KEY = MT.BOOKINGS_MEASURE_KEY
 AND ALL_TRIPS.BKGS_MEASURE_TRANS_TYPE_CODE = MT.BKGS_MEASURE_TRANS_TYPE_CODE
 AND ALL_TRIPS.BOOKINGS_PROCESS_DATE = MT.BOOKINGS_PROCESS_DATE
 AND ALL_TRIPS.SALES_TERRITORY_KEY = MT.SALES_TERRITORY_KEY
 AND ALL_TRIPS.SALES_REP_NUMBER = MT.SALES_REP_NUMBER
 WHERE
 COLLATE( MT.ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3' AND RTRIM( ALL_TRIPS.ANNUITY_TYPE) in (COLLATE('ANNUITY31', 'en-ci-rtrim'), COLLATE('ANNUITY321', 'en-ci-rtrim'))